"""The `claude -p` invocation, as a guard rather than as prose (T2.4). No Docker, no model.

Five configurations were measured to produce a run with **no gramps tools at all** (salvage
note §0): `--tools` with any value, `--safe-mode`, `--bare`, `CLAUDE_CODE_SIMPLE=1`, and
`--disallowedTools` that includes `ToolSearch` — in 2.1.x the MCP tools are deferred, so
`ToolSearch` is the only path to them. Each of those runs looks from the outside like a
catastrophic docstring failure: the model has nothing to call, so it calls nothing, so every
assertion about the tree fails at once. That is the most expensive possible false red, and the
design left it as a sentence in a document.

So the same rule the gate hardening established for assertions applies here: **absence is not
evidence**. A flag that must be present is checked as hard as a flag that must not be — a
missing `--strict-mcp-config` silently connects the developer's own MCP servers, and a run that
grades those is grading somebody else's tools.
"""

from __future__ import annotations

from pathlib import Path

import pytest
from harness.docker_util import ProbeError
from stage2 import driver

CONFIG = Path("/tmp/gwe2e-stage2/mcp.json")
PROMPT = "Please add my grandmother Wendelmark to the tree."


@pytest.fixture(scope="module")
def argv() -> list[str]:
    return driver.build_argv(PROMPT, config=CONFIG)


def flag_value(argv: list[str], flag: str) -> str:
    """The single value after `flag` — `KeyError`-loud rather than silently `None`."""
    return argv[argv.index(flag) + 1]


def test_the_isolation_flags_are_all_present(argv: list[str]) -> None:
    """Each one was measured to remove a distinct source of contamination."""
    assert flag_value(argv, "--setting-sources") == ""
    assert "--disable-slash-commands" in argv
    assert "--strict-mcp-config" in argv
    assert flag_value(argv, "--mcp-config") == str(CONFIG)
    assert flag_value(argv, "--permission-mode") == "bypassPermissions"
    assert "--no-session-persistence" in argv


def test_the_wire_log_flags_are_present(argv: list[str]) -> None:
    """`stream-json` *is* the mandated wire log (decision d); `--verbose` is required with it."""
    assert flag_value(argv, "--output-format") == "stream-json"
    assert "--verbose" in argv


def test_tool_search_is_not_disallowed(argv: list[str]) -> None:
    """The one built-in that must survive: without it the MCP tools are unreachable."""
    assert driver.TOOL_SEARCH not in argv
    assert "Bash" in argv, "the other built-ins are still meant to be denied"


def test_the_model_is_pinned_to_its_canonical_name(argv: list[str]) -> None:
    """An alias lets a rollover move the baseline without a single line changing."""
    assert flag_value(argv, "--model") == driver.MODEL
    assert driver.MODEL.startswith("claude-")


def test_the_prompt_is_the_last_argument_and_stays_one_word(argv: list[str]) -> None:
    assert argv[-1] == PROMPT


def test_the_prompt_is_not_shell_quoted(argv: list[str]) -> None:
    """argv, not a shell string — a quoted prompt would reach the model with its quotes."""
    assert not argv[-1].startswith(("'", '"'))


@pytest.mark.parametrize(
    ("extra", "expected"),
    [
        (["--tools", ""], "--tools"),
        (["--tools", "mcp__gramps__gramps_add_person"], "--tools"),
        (["--tools="], "--tools"),
        (["--safe-mode"], "--safe-mode"),
        (["--bare"], "--bare"),
    ],
)
def test_a_flag_that_kills_the_mcp_tools_is_refused(extra: list[str], expected: str) -> None:
    with pytest.raises(ProbeError, match=expected):
        driver.build_argv(PROMPT, config=CONFIG, extra=extra)


def test_disallowing_tool_search_is_refused() -> None:
    """The fifth killer, and the only one that hides inside a legitimate flag."""
    with pytest.raises(ProbeError, match=driver.TOOL_SEARCH):
        driver.build_argv(PROMPT, config=CONFIG, extra=["--disallowedTools", driver.TOOL_SEARCH])


def test_the_simple_mode_env_var_is_refused() -> None:
    """`CLAUDE_CODE_SIMPLE=1` destroys the subscription OAuth outright — there is no API key."""
    with pytest.raises(ProbeError, match="CLAUDE_CODE_SIMPLE"):
        driver.assert_usable(driver.build_argv(PROMPT, config=CONFIG), {"CLAUDE_CODE_SIMPLE": "1"})


def test_the_simple_mode_env_var_is_refused_whatever_its_value() -> None:
    """It is read as "set", not as "true" — `0` would be just as fatal and just as silent."""
    with pytest.raises(ProbeError, match="CLAUDE_CODE_SIMPLE"):
        driver.assert_usable(driver.build_argv(PROMPT, config=CONFIG), {"CLAUDE_CODE_SIMPLE": "0"})


@pytest.mark.parametrize(
    "dropped",
    ["--strict-mcp-config", "--setting-sources", "--mcp-config", "--verbose", "--model"],
)
def test_a_missing_required_flag_is_refused(argv: list[str], dropped: str) -> None:
    """Absence is the same failure class as a forbidden flag, and just as quiet.

    Without `--strict-mcp-config` the run connects the developer's own MCP servers and grades
    those; without `--verbose` there is no wire log to grade at all.
    """
    without = [item for index, item in enumerate(argv) if item != dropped]

    with pytest.raises(ProbeError, match=dropped):
        driver.assert_usable(without, {})


def test_an_aliased_model_is_refused(argv: list[str]) -> None:
    aliased = [("sonnet" if item == driver.MODEL else item) for item in argv]

    with pytest.raises(ProbeError, match="sonnet"):
        driver.assert_usable(aliased, {})


def test_a_clean_environment_passes(argv: list[str]) -> None:
    """The positive control: the guard must not simply refuse everything."""
    driver.assert_usable(argv, {"HOME": "/home/nobody", "PATH": "/usr/bin"})


def test_the_run_environment_keeps_the_login_and_drops_the_repo(tmp_path: Path) -> None:
    """The subscription lives in `~/.claude`; the run must not inherit our own MCP wiring."""
    environment = driver.run_env({"HOME": "/home/nobody", "CLAUDE_CODE_SIMPLE": "1"})

    assert environment["HOME"] == "/home/nobody"
    assert "CLAUDE_CODE_SIMPLE" not in environment


def test_the_working_directory_must_be_empty(tmp_path: Path) -> None:
    """A `CLAUDE.md` or `.mcp.json` in the run cwd is discovered and is contamination."""
    (tmp_path / "CLAUDE.md").write_text("be helpful", encoding="utf-8")

    with pytest.raises(ProbeError, match="CLAUDE.md"):
        driver.assert_clean_cwd(tmp_path)


def test_an_empty_working_directory_passes(tmp_path: Path) -> None:
    driver.assert_clean_cwd(tmp_path)


def test_the_verified_cli_version_is_recorded() -> None:
    """Every flag above was validated by execution against this version, and only this one."""
    assert driver.VERIFIED_CLI_VERSION == "2.1.220"
